interface BooleanSetting extends BaseSetting {
    type: "boolean";
    default: boolean;
}

interface StringSetting extends BaseSetting {
    type: "string";
    default: string;
    placeholder?: string;
    multiline?: boolean;
}

interface NumberSetting extends BaseSetting {
    type: "number";
    default: number;
    min?: number;
    max?: number;
    step?: number;
}

interface SelectSetting<V extends string = string> extends BaseSetting {
    type: "select";
    default: V;
    options: readonly { label: string; value: V; }[];
}

interface KeybindSetting extends BaseSetting {
    type: "keybind";
    default: string;
}

interface PluginDefinition<S extends SettingsSchema = SettingsSchema> {
    settings?: S;
    patches?: SourcePatch[];
    css?: string;
    flux?: Record<string, (action: FluxAction) => void>;
    start?(ctx: PluginContext<S>): void | Promise<void>;
    stop?(ctx: PluginContext<S>): void;
    settingsPanel?(ctx: PluginContext<S>): ReactNode;
    [key: string]: unknown;
}

interface CommandContext {
    channel: any;
    guild?: any;
    rawOptions: { name: string; type: number; value: any; }[];
    reply(content: string): void;
}

interface CommandDefinition {
    name: string;
    description: string;
    options?: CommandOption[];
    predicate?(context: { channel: any; guild?: any; }): boolean;
    execute(args: Record<string, any>, context: CommandContext): void | CommandResult | Promise<void | CommandResult>;
}

interface CommandOption {
    name: string;
    description: string;
    type?: CommandOptionTypeName | number;
    required?: boolean;
    choices?: { name: string; value: string | number; }[];
}

interface MenuComponents {
    Item: ComponentType<MenuItemProps>;
    Group: ComponentType<{ label?: ReactNode; children?: ReactNode; }>;
    Separator: ComponentType<{}>;
    CheckboxItem: ComponentType<MenuCheckboxItemProps>;
    RadioItem: ComponentType<MenuRadioItemProps>;
    SwitchItem: ComponentType<MenuCheckboxItemProps>;
    ControlItem: ComponentType<MenuControlItemProps>;
    TextInput: ComponentType<any>;
}

interface MenuItemProps {
    id: string;
    label?: ReactNode;
    action?(event: MouseEvent): void;
    disabled?: boolean;
    color?: "default" | "danger" | "brand" | "premium" | "positive";
    icon?: ComponentType<any>;
    subtext?: ReactNode;
    children?: ReactNode;
    render?(props: any): ReactNode;
}

interface LayerOptions {
    className?: string;
    onClosed?(): void;
}

interface PanelIconProps {
    width?: number;
    height?: number;
}

interface PanelToggle {
    label(): string;
    tooltip(checked: boolean): string;
    icon(checked: boolean): ComponentType<PanelIconProps>;
    isChecked(): boolean;
    subscribe(onChange: () => void): () => void;
    alert(checked: boolean): boolean;
    toggle(): void;
}

interface ToastOptions {
    type?: ToastType;
    duration?: number;
    position?: "top" | "bottom";
}

interface FluxAction {
    type: string;
    [key: string]: any;
}

interface FluxDispatcher {
    dispatch(action: FluxAction): Promise<void>;
    subscribe(type: string, handler: (action: FluxAction) => void): void;
    unsubscribe(type: string, handler: (action: FluxAction) => void): void;
}

interface FoundExport<T = any> {
    id: string;
    exports: any;
    key: string | undefined;
    value: T;
}

interface Module {
    id: PropertyKey;
    loaded: boolean;
    exports: any;
}

interface WebpackRequire {
    (id: PropertyKey): any;
    m: Record<PropertyKey, ModuleFactory>;
    c: Record<PropertyKey, Module>;
    d(exports: object, definition: Record<string, () => unknown>): void;
    e(chunkId: PropertyKey): Promise<unknown>;
    o(object: object, key: PropertyKey): boolean;
    p: string;
}

interface DropdownProps<V extends string> {
    label: string;
    options: readonly { label: string; value: V; disabled?: boolean; }[];
    value: V;
    onChange(value: V): void;
    id?: string;
    labelledBy?: string;
    disabled?: boolean;
    className?: string;
}

